/**
 * Responsive variant widths. These are generated by
 * src/app/api/upload/route.ts via sharp and consumed by
 * src/lib/image-loader.ts.
 *
 * Changing this list requires regenerating existing images — the upload
 * route writes one file per width and nothing backfills. Keep in sync with:
 *   - next.config.ts              (images.deviceSizes)
 *   - src/app/api/upload/route.ts (VARIANT_WIDTHS)
 */
export const VARIANT_WIDTHS = [400, 800, 1200, 2000] as const;

export type VariantWidth = (typeof VARIANT_WIDTHS)[number];

/**
 * Admin-uploaded image variants live in Supabase Storage, not on local
 * disk. Until 2026-10-14 they lived under php/uploads/ on SiteGround
 * itself, which only worked because the old deploy.yml rsync carefully
 * excluded that one directory from `--delete` on every deploy (see
 * project-admin-panel memory's CORS/publish section for how much care that
 * took to get right). SiteGround's Node.js Projects auto-rebuild-and-
 * redeploy the whole app from GitHub on every push (docs/NODE_MIGRATION.md)
 * — there's no equivalent "leave this one folder alone" exclusion available
 * in that model, and PaaS-style rebuild-from-source hosting generally
 * shouldn't be trusted to preserve arbitrary local disk writes across
 * deploys at all. Supabase Storage sidesteps the whole problem: it's
 * already the system of record for everything else these images are
 * attached to, and it survives app redeploys by construction.
 */
const STORAGE_BUCKET = "project-images";

function storagePublicUrl(objectPath: string): string {
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL!.replace(/\/+$/, "");
  return `${base}/storage/v1/object/public/${STORAGE_BUCKET}/${objectPath}`;
}

/** Smallest generated variant at least as wide as `width`; largest otherwise. */
export function nearestVariant(width: number): VariantWidth {
  return (
    VARIANT_WIDTHS.find((w) => w >= width) ??
    VARIANT_WIDTHS[VARIANT_WIDTHS.length - 1]
  );
}

/**
 * `storagePath` is stored in Postgres without a width or extension
 * (e.g. "uploads/<project_id>/<uuid>"); each variant lives alongside it in
 * the `project-images` Storage bucket as "<storagePath>-<width>.webp".
 */
export function variantUrl(storagePath: string, width: number): string {
  const base = storagePath.replace(/^\/+/, "");
  return storagePublicUrl(`${base}-${nearestVariant(width)}.webp`);
}
